{
  "shot": {
    "composition": "中景镜头，使用35mm镜头，配备索尼VENICE摄影机，浅景深，焦点精准对准薛夫人，背景人物与环境适度虚化以突出主体",
    "camera_motion": "静止镜头，无任何移动或晃动，保持画面稳定以突出人物神态与仪式感"
  },
  "subject": {
    "description": "一位25岁的东亚女性，面容清冷，五官精致，眉目如画，鼻梁挺直，唇色淡雅，眼神锐利而深邃，散发出高贵与威严的气质。她身姿挺拔，身形纤细而优雅，黑色长发高高盘起，发髻上点缀着珍珠与银饰，散发出古典贵气。",
    "wardrobe": "身穿一袭淡蓝色内衬、粉红色裙摆、外披红色长袍的汉服，长袍上绣有金色凤凰图案，腰间系着淡粉色丝带，脚踩一双绣花木履，整体造型典雅华贵，极具传统贵妇气质"
  },
  "scene": {
    "location": "侯府内婚宴厅堂，雕梁画栋，红墙金柱，悬挂着红色帷幔与金色装饰，厅堂中央设有一张长桌，两侧摆满酒席与供品",
    "time_of_day": "傍晚，夕阳余晖透过雕花窗棂洒入厅堂，光线柔和温暖",
    "environment": "厅堂内宾客满座，男女老少皆着华服，或交谈或举杯，气氛热闹而庄重。背景中可见红绸幔帐、雕花木桌、酒杯与果盘，地面铺有红金相间的地毯，两侧设有高脚凳与矮凳，整体氛围富丽堂皇"
  },
  "visual_details": {
    "action": "薛夫人在婚宴现场冷冽扫视众人，嘴角勾起一抹冷笑，随后优雅拿起酒杯与宾客对饮，展现出她内心的傲慢与掌控力",
    "props": "酒杯、果盘、红绸幔帐、雕花木桌、高脚凳、矮凳、烛台、酒壶、红色桌布、金色凤凰刺绣长袍",
    "action_sequence": [
      "0-1s: 薛夫人缓缓抬起眼眸，冷冽的视线扫过全场宾客，嘴角微微上扬，露出一抹冷笑",
      "1-2s: 她右手轻抬，优雅拿起面前的酒杯，目光锁定前方一位宾客，眼神中流露出不屑与掌控",
      "2-3s: 她轻轻抿唇，将酒杯举至唇边，姿态从容，仿佛在等待某个时机",
      "3-4s: 她突然将酒杯与宾客对饮，动作流畅而优雅，酒液在杯中荡漾，映出她冷艳的面容",
      "4-5s: 她放下酒杯，嘴角笑意加深，眼神依旧锐利，仿佛在无声宣告自己的地位与气场"
    ]
  },
  "cinematography": {
    "lighting": "暖金色夕阳光线从窗棂斜射入厅堂，柔和地打在薛夫人身上，形成明暗对比，突出其冷艳气质；背景辅以柔和的烛光与灯笼光，营造出温暖而庄重的氛围",
    "tone": "冷峻而优雅，带有贵族仪式感与戏剧张力，画面色调以红、金、蓝为主，突出贵妇身份与内心傲慢"
  }
}

